package com.ryanjei.orushio.pve.map;

import com.ryanjei.orushio.pve.domain.MapProfileId;import com.ryanjei.orushio.pve.persistence.*;import java.nio.file.*;import java.time.Instant;import java.util.*;
public final class YamlMapProfileRepository implements MapProfileRepository {private final Path mapsRoot;public YamlMapProfileRepository(Path mapsRoot){this.mapsRoot=mapsRoot.toAbsolutePath().normalize();}public List<MapProfile> findAll(){if(!Files.isDirectory(mapsRoot))return List.of();try(var stream=Files.list(mapsRoot)){return stream.filter(Files::isDirectory).map(p->load(p.resolve("profile.yml"))).flatMap(Optional::stream).sorted(Comparator.comparing(p->p.mapId().value())).toList();}catch(Exception e){throw new RepositoryException("マップ一覧を読み込めません。",e);}}public Optional<MapProfile> find(MapProfileId id){return load(path(id).resolve("profile.yml"));}public void save(MapProfile p){Map<String,String> v=new LinkedHashMap<>();v.put("schemaVersion","1");v.put("mapId",p.mapId().value());v.put("displayName",p.displayName());v.put("enabled",Boolean.toString(p.enabled()));v.put("templateDirectory",p.templateDirectory());v.put("createdAt",p.createdAt().toString());p.points().forEach((k,list)->v.put("points."+k,encodePoints(list)));p.areas().forEach((k,list)->v.put("areas."+k,encodeAreas(list)));new AtomicYamlStore(path(p.mapId()).resolve("profile.yml")).write(v);}public void delete(MapProfileId id){try{Files.deleteIfExists(path(id).resolve("profile.yml"));}catch(Exception e){throw new RepositoryException("MapProfileを削除できません。",e);}}private Optional<MapProfile> load(Path file){return new AtomicYamlStore(file).read().map(v->{MapProfileId id=new MapProfileId(v.get("mapId"));Map<String,List<BlockPoint>> points=new LinkedHashMap<>();Map<String,List<Cuboid>> areas=new LinkedHashMap<>();v.forEach((k,val)->{if(k.startsWith("points."))points.put(k.substring(7),decodePoints(val));if(k.startsWith("areas."))areas.put(k.substring(6),decodeAreas(val));});return new MapProfile(id,v.get("displayName"),Boolean.parseBoolean(v.get("enabled")),v.get("templateDirectory"),points,areas,Instant.parse(v.get("createdAt")));});}private Path path(MapProfileId id){Path p=mapsRoot.resolve(id.value()).normalize();if(!p.getParent().equals(mapsRoot))throw new RepositoryException("mapIdの保存先が不正です。");return p;}private static String encodePoints(List<BlockPoint> l){return l.stream().map(p->p.x()+","+p.y()+","+p.z()+","+p.yaw()+","+p.pitch()).collect(java.util.stream.Collectors.joining(";"));}private static List<BlockPoint> decodePoints(String s){if(s.isBlank())return List.of();return Arrays.stream(s.split(";")).map(v->{String[] a=v.split(",");return new BlockPoint(Integer.parseInt(a[0]),Integer.parseInt(a[1]),Integer.parseInt(a[2]),Float.parseFloat(a[3]),Float.parseFloat(a[4]));}).toList();}private static String encodeAreas(List<Cuboid> l){return l.stream().map(a->a.minX()+","+a.minY()+","+a.minZ()+","+a.maxX()+","+a.maxY()+","+a.maxZ()).collect(java.util.stream.Collectors.joining(";"));}private static List<Cuboid> decodeAreas(String s){if(s.isBlank())return List.of();return Arrays.stream(s.split(";")).map(v->{String[] a=v.split(",");return new Cuboid(Integer.parseInt(a[0]),Integer.parseInt(a[1]),Integer.parseInt(a[2]),Integer.parseInt(a[3]),Integer.parseInt(a[4]),Integer.parseInt(a[5]));}).toList();}}
